<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {getSession,login,logout,refreshCsrf} from '../FleetAndDocuments/api';
import type {Session} from '../FleetAndDocuments/contracts';
import {request,failure} from '../Administration/api';
import DriverTrips from './DriverTrips.vue';
import BillingReview from './BillingReview.vue';
import '../Workshop/workshop.css';
import SharedNavigation from './SharedNavigation.vue';
const section=document.getElementById('system-app')?.dataset.section??'login';
const session=ref<Session|null>(null),loading=ref(true),busy=ref(false),error=ref(''),username=ref(''),password=ref('');
const billingLocked=ref(false);
function acceptSession(actor:Session):void{session.value=actor;}
function guardNavigation(event:MouseEvent):void{if(billingLocked.value&&event.target instanceof Element&&event.target.closest('a'))event.preventDefault();}
const counters=ref<{key:string;label:string;value:number;href:string}[]>([]);let generation=0;
async function report(e:unknown):Promise<void>{const problem=failure(e);error.value=problem.message;if([401,403].includes(problem.status)){session.value=null;counters.value=[];}}
async function home():Promise<void>{const result=await request<{home:string}>('/navigation');window.location.assign(result.home);}
async function signIn():Promise<void>{if(busy.value)return;busy.value=true;error.value='';try{await refreshCsrf();session.value=await login(username.value,password.value);password.value='';if(section!=='billing'||!session.value.roles.some(role=>['administrator','secretary'].includes(role)))await home();}catch(e){await report(e);}finally{password.value='';busy.value=false;}}
async function exit():Promise<void>{if(busy.value||billingLocked.value)return;busy.value=true;try{await logout();session.value=null;counters.value=[];window.location.assign('/login');}catch(e){await report(e);}finally{busy.value=false;}}
async function load():Promise<void>{const current=++generation;loading.value=true;error.value='';try{const actor=await getSession();if(current!==generation)return;session.value=actor;if(section==='login'){await home();return;}if(section==='dashboard'){const data=await request<{counters:typeof counters.value}>('/dashboard');if(current===generation)counters.value=data.counters;}}catch(e){if(current===generation&&!(section==='login'&&failure(e).status===401))await report(e);}finally{if(current===generation)loading.value=false;}}
onMounted(load);onBeforeUnmount(()=>generation++);
</script>
<template><div @click.capture="guardNavigation" class="administration-shell min-h-screen bg-blue-50 text-slate-900"><header class="bg-white border-b border-blue-200"><div class="max-w-7xl mx-auto p-5 flex flex-wrap justify-between gap-4"><div><p class="text-blue-800 font-semibold">Transportes Líquidos</p><h1 class="text-2xl font-bold">{{section==='dashboard'?'Panel general':section==='driver'?'Viajes asignados':section==='billing'?'Facturación de transporte':'Acceso al sistema'}}</h1></div><button v-if="session" class="btn-secondary" :disabled="busy||billingLocked" @click="exit">Cerrar sesión</button><SharedNavigation :session="session" :disabled="busy||billingLocked"/></div></header><main class="max-w-7xl mx-auto p-4 md:p-6 space-y-5"><p v-if="loading" role="status">Consultando sesión…</p><p v-if="error" class="notice-error" role="alert">{{error}}</p><form v-if="!loading&&!session" class="panel max-w-md mx-auto space-y-4" @submit.prevent="signIn"><h2 class="text-xl font-semibold">Iniciar sesión</h2><label class="block">Usuario<input v-model="username" class="field mt-2" autocomplete="username" required :disabled="busy"></label><label class="block">Contraseña<input v-model="password" class="field mt-2" type="password" autocomplete="current-password" required :disabled="busy"></label><button class="btn-primary" :disabled="busy">{{busy?'Ingresando…':'Iniciar sesión'}}</button></form><section v-if="!loading&&session&&section==='dashboard'" aria-label="Resumen general" class="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><a v-for="counter in counters" :key="counter.key" :href="counter.href" class="panel hover:border-blue-500"><h2 class="text-blue-800 font-semibold">{{counter.label}}</h2><p class="text-3xl font-bold mt-3">{{new Intl.NumberFormat('es-CR').format(counter.value)}}</p><span class="text-sm text-blue-700">Consultar registros →</span></a></section><p v-if="!loading&&session&&section==='dashboard'" class="text-sm text-slate-600">Conteos de registros actuales del sistema. No representan ingresos ni indicadores financieros.</p><DriverTrips v-if="!loading&&session&&section==='driver'" @denied="report"/><BillingReview v-if="section==='billing'" :session="session" @denied="report" @lock="billingLocked=$event" @session="acceptSession"/><button v-if="error" class="btn-secondary" :disabled="busy||loading||billingLocked" @click="load">Comprobar sesión y actualizar</button></main></div></template>
